/* Mandate lookup. GENERATED by tools/blog/build-mandate-lookup.py.
   Do not edit by hand: every claim is read out of data/funding/*.json and
   asserted at build time. Edit the data, rebuild. */
(function () {
  "use strict";
  if (location.pathname.replace(/\/+$/, "") !== "/insurance-terminology") return;
  var D = {"states":{"new-jersey":{"name":"New Jersey","effective":"February 9, 2010. Chapter 115 applies to all health insurance policies issued or renewed on or after February 9, 2010 that provide hospital and medical expense benefits, including all health maintenance organization and all health service corporation contracts.","ageLimit":"Coverage of behavioral interventions based on applied behavior analysis is required for an individual who is under 21 years of age and diagnosed with autism. The separate requirements to cover screening and diagnosis, and medically necessary physical, occupational and speech therapy, are not stated with an age limit in Bulletin 10-02's summary of the law.","cap":36000,"capStatus":"rarely_applicable","visits":"No visit or hour cap is set by Chapter 115. Carriers may not reduce the physical, occupational, speech or behavioral therapy benefits otherwise available under the contract because those services were used to treat autism or another developmental disability. A separate set of benefits may be established for these services only on terms the same as or more favorable than those applying to other conditions, and DOBI \"will not approve limits for physical therapy, occupational therapy or speech therapy for treatment of autism or other developmental disabilities that establish a maximum number of days of therapy measured from the date of diagnosis or inception of treatment, or benefit limits established on a per illness or injury basis.\"","diagnosis":"DOBI reads \"autism\" in Chapter 115 to mean autism and related conditions grouped under Autism Spectrum Disorder, and treats diagnostic codes using 299 in the DSM-IV-TR or ICD as autism for compliance purposes. Carriers may choose to exclude 299.1 and 299.8 where the diagnosis is clearly Childhood Disintegrative Disorder or Rett's Disorder, but should still consider whether those diagnoses meet the developmental disability definition at N.J.S.A. 30:6D-3, which Chapter 115 also covers.","order":"Bulletin 10-02 sets no prescription or physician referral precondition for the commercial mandate. It conditions the ABA benefit on medical necessity and on who delivers the service: DOBI \"believes carriers should consider behavioral interventions based on ABA and related structured behavior program services eligible for benefits if administered directly by or under the direct supervision of an individual who is credentialed by the national Behavior Analyst Certification Board as either: a Board Certified Behavior Analyst - Doctoral (BCBA-D); or a Board Certified Behavior Analyst (BCBA)\". NJ FamilyCare does impose a recommendation requirement; see the medicaid block.","selfFunded":"Yes, and it is the single most important thing to check before relying on anything else on this page. New Jersey's utilization management appeal rules and the Independent Health Care Appeals Program do not reach self-funded plans: DOBI states its answers \"do not apply to self-funded plans, to policies issued and delivered in a state other than New Jersey, or to limited benefits plans that do not provide hospital or medical expense benefits.\" The same boundary is why a self-funded employer plan is not obliged by Chapter 115.","selfFundedTell":"Ask the employer's plan administrator whether the plan is self-funded or fully insured, and read the Summary Plan Description, which the plan administrator must give participants free of charge and which \"provides a detailed overview of the plan: how it works, what benefits it provides, how to file a claim for benefits, and any limitations that may apply.\" A denial letter is the other quick tell, because \"the external review process used by the plan depends on whether the plan is self-funded or provides benefits through an insurance company. The claim denial notice from your plan will describe the external process and your rights.\" A denial that points to a federal external review route rather than to New Jersey's IHCAP indicates a self-funded plan.","medicaidAge":"Under 21. The state plan says these \"EPSDT services are available to Medicaid beneficiaries under the age of twenty-one with an ASD diagnosis made by a qualified licensed practitioner.\"","medicaidPA":"Yes, and where the request goes depends on how the child is covered. For NJ FamilyCare fee for service, prior authorization runs through the Interim Managing Entity on 1.844.276.2444, with a dedicated \"DMAHS and Autism Line (ABA & DIR Services)\" on 609.588.8522 or MAHS.ASDinquiries@dhs.nj.gov, and provider enrollment through Gainwell Technologies Provider Services on 1.800.776.6334. For a child in a managed care plan, authorization goes to that plan; UnitedHealthcare Community Plan, for example, routes ABA and DIR requests through Optum's Provider Express autism portal. Behavioral health access for children also runs through PerformCare on 1.877.652.7624.","appealInternal":"180 days. DOBI: \"Persons enrolled in a group health plan or in an individual plan have 180 days following the receipt of an adverse UM determination to file a Stage 1 appeal. The time-frame for filing a Stage 2 appeal, if applicable, is 180 days.\" NJ FamilyCare members have 60 days to file a Stage 1 appeal. The carrier should issue a Stage 1 determination within 10 business days, or within 72 hours where the appeal involves urgent or emergency care, and a Stage 2 determination within 20 business days.","appealBody":"The Independent Health Care Appeals Program, run by the New Jersey Department of Banking and Insurance. Cases are decided by Independent Utilization Review Organizations; since January 1, 2022 the vendor is Maximus Federal Services.","appealDeadline":"Four months. DOBI: appeals \"must be filed within the four-month period after the covered person or health care provider receives the final UM appeal determination.\"","appealExpedited":"Yes. Expedited external reviews \"are decided by the IURO within 48 hours from when the appeal request was submitted,\" and are available for admission requests, continued stays, or where the standard review time frame \"would seriously jeopardize your life or health.\" An appeal is normally ineligible if \"the internal appeal process has not been completed,\" but exceptions include where the carrier failed to meet its own timeframes, or where the family or provider applied for expedited external review at the same time as expedited internal review.","flagged":[]},"georgia":{"name":"Georgia","effective":"Two dates matter. The original mandate reaches plans \"issued or renewed in Georgia on or after July 1, 2015.\" The expansion to age 20 and $35,000 came through SB 118, signed May 8, 2018, which states \"This Act shall become effective January 1, 2019.\"","ageLimit":"20 years of age or under. SB 118 struck \"six\" and inserted \"20\": coverage is required \"for an individual covered under a policy or contract who is 20 years of age or under.\"","cap":35000,"capStatus":"applies_to_aba_only","visits":"None permitted. \"The policy or contract shall not include any limits on the number of visits.\"","diagnosis":"A licensed physician or licensed psychologist. The plan \"shall provide coverage for any assessments, evaluations, or tests by a licensed physician or licensed psychologist to diagnose whether an individual has an autism spectrum disorder.\"","order":"No prescription requirement, but a medical necessity determination and an annual redetermination. Coverage for ABA is required \"when it is determined by the covering entity that the treatment is medically necessary health care according to established criteria. A licensed physician or licensed psychologist may be required to demonstrate ongoing medical necessity for coverage provided under this Code section at least annually.\" Note that SB 118 moved the medical necessity determination from the physician or psychologist to the covering entity.","selfFunded":"Yes. Georgia's mandate is written as a requirement on \"accident and sickness contracts, policies, or benefit plans,\" that is, on insurance. An employer that self-funds buys no such contract, so Ava's Law does not bind it, and neither does Georgia's independent review process, which applies to managed care entities regulated by the state.","selfFundedTell":"Ask the employer's plan administrator whether the plan is self-funded or fully insured, and read the Summary Plan Description, which the administrator must provide free of charge and which \"provides a detailed overview of the plan: how it works, what benefits it provides, how to file a claim for benefits, and any limitations that may apply.\" The denial letter is the other tell: \"the external review process used by the plan depends on whether the plan is self-funded or provides benefits through an insurance company. The claim denial notice from your plan will describe the external process and your rights.\" A denial pointing to a federal external review route rather than Georgia's independent review indicates a self-funded plan.","medicaidAge":"Under 21. \"Autism Spectrum Services are for individuals under the age of 21.\" The manual adds that \"therapy can range from 10-30 hours per week, or more if medically necessary, and requires active parent/caregiver participation and involvement.\"","medicaidPA":"Required, without exception, and time limited. \"Prior Authorization (PA) is required for all Medicaid-covered ABS. Services without a PA will not be covered. ABS is authorized in six (6) month increments. All ABS PAs must be requested by the enrolled QHCP.\" A separate PA is needed for the assessment and for treatment.","appealInternal":"The managed care entity's internal grievance process must be exhausted before independent review. Rule 120-2-111-.04(1)(a) conditions eligibility on the fact that \"the eligible enrollee has received notice of an adverse outcome pursuant to a grievance procedure.\" The deadline for starting that internal grievance is set by the plan, so use the date printed on the denial letter.","appealBody":"An independent review organization certified under the Patient's Right to Independent Review Act, administered by the Georgia Office of the Commissioner of Insurance and Safety Fire. \"House Bill 1013, signed by Governor Brian P. Kemp on April 4, 2022, transfers the duties under the Patient's Rights to Independent Review Act from DCH to the Georgia Office of Commissioner of Insurance and Safety Fire. Effective July 1, 2022, send independent review requests to\" OCI.","appealDeadline":"unresolved from primary sources. Chapter 120-2-111 as published on the Secretary of State's rules site requires that the internal grievance be exhausted and directs requests to the Department at adminproc@oci.ga.gov, but the chapter text checked here states no filing deadline. Families should treat the deadline printed on their final denial letter as controlling and file immediately, and confirm with OCI before assuming any window. Do not publish a specific number of days for Georgia until this is sourced.","appealExpedited":"Yes. Rule 120-2-111-.06(8): \"a decision by the expert reviewer shall be rendered within 72 hours (three calendar days) after the expert reviewer's receipt of all available requested documentation.\" Standard reviews run longer: under Rule 120-2-111-.06(5) the reviewer \"shall make a determination within 15 working days after expiration of all additional information time limits.\"","flagged":["appealDeadline"]},"north-carolina":{"name":"North Carolina","effective":"\"This act becomes effective July 1, 2016, and applies to insurance contracts issued, renewed, or amended on or after that date.\"","ageLimit":"Coverage for adaptive behavior treatment \"may be limited to individuals 18 years of age or younger.\" Note the shape of that sentence: the age limit is something the plan is permitted to apply, not a statement that older people are excluded from the rest of the section. The screening, diagnosis and treatment obligation in subsection (b) is not written with an age limit.","cap":40000,"capStatus":"stale_base_indexed","visits":"The statute sets no visit or hour limit for adaptive behavior treatment. Its stated limit is the annual dollar maximum in subsection (c).","diagnosis":"Autism spectrum disorder \"as defined by the most recent edition of the Diagnostic and Statistical Manual of Mental Disorders (DSM) or the most recent edition of the International Statistical Classification of Diseases.\" No insurer \"shall terminate coverage or refuse to issue, amend, or renew coverage to an individual solely because the individual is diagnosed with autism spectrum disorder or has received treatment for autism spectrum disorder.\"","order":"Yes, North Carolina requires an order. Treatment must be \"ordered by a licensed physician or licensed psychologist\" and \"provided or supervised by\" one of the listed professionals: psychologists, psychiatrists, developmental pediatricians, speech and language pathologists, occupational therapists, clinical social workers, mental health counselors, marriage and family therapists, or a board certified behavior analyst. This is the sharpest practical difference from New Jersey, where no order is required for the commercial mandate.","selfFunded":"Yes, and North Carolina says so in plain words rather than leaving it to be inferred. The Department of Insurance states that external review \"does not apply to self-funded employer health plans,\" and the mandate itself binds \"insurance contracts,\" which a self-funded plan does not buy.","selfFundedTell":"Ask the employer's plan administrator whether the plan is self-funded or fully insured, and read the Summary Plan Description, which the administrator must provide free of charge and which \"provides a detailed overview of the plan: how it works, what benefits it provides, how to file a claim for benefits, and any limitations that may apply.\" The denial letter is the faster tell: \"the external review process used by the plan depends on whether the plan is self-funded or provides benefits through an insurance company. The claim denial notice from your plan will describe the external process and your rights.\" A denial that routes you to a federal external review rather than to Smart NC indicates a self-funded plan.","medicaidAge":"Under 21, through the EPSDT provision at subsection 2.2.1, \"EPSDT Special Provision: Exception to Policy Limitations for a Medicaid Beneficiary under 21 Years of Age.\" NC Medicaid also covers RB-BHT for adults: CMS approved the service for beneficiaries over the age of 21 effective July 1, 2021, \"when the intervention provided is supported by credible scientific or clinical evidence, as appropriate for the beneficiary's age range,\" and Clinical Coverage Policy 8F was updated to reflect it. North Carolina is unusual in this: most state Medicaid autism benefits stop at 21.","medicaidPA":"Required, and the authorization window narrows as hours rise. \"RB-BHT services are provided under a prior authorized Treatment Plan that has measurable goals over a specific timeline for the specific beneficiary being treated as developed by a Licensed Qualified Autism Service Provider (LQASP). Services provided without prior authorization are not considered for payment or reimbursement except in the case of retroactive Medicaid eligibility.\" For plans of 16 hours or fewer per week, Medicaid \"covers up to 180-calendar days for the initial authorization period\"; for plans of more than 16 hours per week, \"up to 90 calendar days.\" Reauthorization follows the same split, at least every 180 or every 90 calendar days. Being under 21 does not remove the requirement: \"the fact that the beneficiary is under 21 years of age does NOT eliminate the requirement for prior approval.\"","appealInternal":"The insurer's internal appeal must be finished first: one of Smart NC's eligibility criteria is that \"you have exhausted your insurer's appeals process,\" unless the request qualifies for the expedited route. The deadline for starting that internal appeal is set by the plan, so use the date printed on the denial letter.","appealBody":"Smart NC, the consumer assistance program within the North Carolina Department of Insurance, which arranges review by an independent review organization.","appealDeadline":"120 days. The request must be \"submitted within 120 days of receiving your insurer's final decision on appeal.\" For an expedited external review the window is 120 days from either the initial denial or the appeal decision. The other eligibility criteria are that the coverage type is subject to external review, that the request concerns \"an insurer's medical necessity determination that resulted in a denial,\" that \"you had coverage in effect with the insurer at the time the services were requested,\" and that \"the service for which coverage was denied appears to be a covered benefit.\"","appealExpedited":"Yes, available \"in cases where the time involved in obtaining a final decision can have an impact on a person's health,\" with a decision \"within three days\" of submission. The expedited route can be used without first exhausting the internal appeal.","flagged":[]}}};

  // Insert above the terms section. No Designer edit needed, and if the
  // heading is ever renamed the widget simply does not render rather than
  // landing somewhere senseless.
  var anchor = null;
  var heads = document.querySelectorAll("h2, h3");
  for (var i = 0; i < heads.length; i++) {
    if ((heads[i].textContent || "").trim().indexOf("Common Insurance Terms to Know") === 0) {
      anchor = heads[i]; break;
    }
  }
  if (!anchor) return;

  var root = document.createElement("div");
  root.id = "mm-mlw";
  anchor.parentNode.insertBefore(root, anchor);

  root.innerHTML = [
    '<div class="mm-mlw-box">',
    '  <div class="mm-mlw-h">What is your plan actually obliged to cover?</div>',
    '  <p class="mm-mlw-sub">Three questions. The answers come from the statute, the Medicaid manual and the insurance regulator in your state, each dated.</p>',
    '  <div class="mm-mlw-row">',
    '    <label>State<select id="mm-mlw-state"></select></label>',
    '    <label>Your plan<select id="mm-mlw-plan">',
    '      <option value="insured">Bought from an insurer</option>',
    '      <option value="selffunded">Self-funded by my employer</option>',
    '      <option value="unsure">I am not sure</option>',
    '      <option value="medicaid">Medicaid</option>',
    '    </select></label>',
    '    <label>Child\'s age<input id="mm-mlw-age" type="number" min="0" max="30" step="1" value="6"></label>',
    '  </div>',
    '  <div id="mm-mlw-out" class="mm-mlw-out"></div>',
    '</div>'
  ].join("");

  var sel = root.querySelector("#mm-mlw-state");
  Object.keys(D.states).forEach(function (k) {
    var o = document.createElement("option");
    o.value = k; o.textContent = D.states[k].name; sel.appendChild(o);
  });

  function p(html) { return "<p>" + html + "</p>"; }
  function note(html) { return '<p class="mm-mlw-note">' + html + "</p>"; }

  function render() {
    var s = D.states[sel.value];
    var plan = root.querySelector("#mm-mlw-plan").value;
    var age = parseInt(root.querySelector("#mm-mlw-age").value, 10);
    var out = [];

    if (plan === "unsure") {
      out.push(p("<b>Find this out first. It changes every other answer.</b>"));
      out.push(p(s.selfFundedTell));
      out.push(note("Come back to this once you know. Until then nothing below is reliable for your family."));
      root.querySelector("#mm-mlw-out").innerHTML = out.join("");
      return;
    }

    if (plan === "selffunded") {
      out.push(p("<b>The " + s.name + " mandate does not reach your plan.</b>"));
      out.push(p(s.selfFunded));
      out.push(note("This is not the same as having no rights. Self-funded plans carry federal appeal rights, and many cover ABA without being compelled to. It does mean the state cap, the state deadline and the state regulator are not levers you hold."));
      root.querySelector("#mm-mlw-out").innerHTML = out.join("");
      return;
    }

    if (plan === "medicaid") {
      out.push(p("<b>Medicaid in " + s.name + ".</b>"));
      out.push(p("<b>Age.</b> " + s.medicaidAge));
      out.push(p("<b>Prior authorization.</b> " + s.medicaidPA));
      out.push(note("Medicaid appeals run through the Medicaid process, not the insurance regulator named below."));
      root.querySelector("#mm-mlw-out").innerHTML = out.join("");
      return;
    }

    // fully insured
    out.push(p("<b>The " + s.name + " mandate applies to your plan.</b> " + s.effective));
    out.push(p("<b>Age.</b> " + s.ageLimit));
    if (!isNaN(age) && age >= 21) {
      out.push(note("At " + age + ", read that age wording closely. Several of these limits are written as something a plan <i>may</i> apply rather than something it must, and the Medicaid position can differ from the insurance one."));
    }
    out.push(p("<b>Dollar cap.</b> $" + s.cap.toLocaleString("en-US") + " a year, with a catch. " + capCatch(s.capStatus)));
    out.push(p("<b>Visit limits.</b> " + s.visits));
    out.push(p("<b>Who has to diagnose it.</b> " + s.diagnosis));
    out.push(p("<b>Do you need an order first?</b> " + s.order));
    out.push(p("<b>If you are refused.</b> " + s.appealInternal));
    out.push(p("<b>Then external review.</b> " + s.appealBody));
    out.push(p("<b>How long you have.</b> " + s.appealDeadline));
    out.push(p("<b>If it is urgent.</b> " + s.appealExpedited));

    root.querySelector("#mm-mlw-out").innerHTML = out.join("");
  }

  function capCatch(status) {
    if (status === "rarely_applicable") {
      return "Your plan often cannot lawfully apply it. Ask the insurer to confirm in writing whether it is applying a dollar maximum to ABA, and why.";
    }
    if (status === "stale_base_indexed") {
      return "That figure is a base the statute has indexed for years, not the live ceiling, and we could not find the current amount published anywhere citable. Ask your insurer for it in writing.";
    }
    return "It applies to applied behavior analysis specifically, and it is a ceiling a plan may apply rather than a budget you are given.";
  }

  root.addEventListener("input", render);
  root.addEventListener("change", render);
  render();
})();
